'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs/promises'),path=require('node:path');
const {FileStore}=require('../desktop/file-store.cjs'),{preview,apply}=require('../desktop/obsidian-sync.cjs');
test('simple lists roundtrip between Fomo rich text and Obsidian Markdown',async t=>{
 const root=await fs.mkdtemp(path.join(process.cwd(),'work','obsidian-test-'));t.after(()=>fs.rm(root,{recursive:true,force:true}));const vault=path.join(root,'vault');await fs.mkdir(vault);const store=new FileStore(path.join(root,'data')),state=await store.init(),next=structuredClone(state),now=new Date().toISOString();next.memos.push({id:'list',content:'标题\n- 一项\n- 二项',html:'<p>标题</p><ul><li><p>一项</p></li><li><p>二项</p></li></ul>',created:now,updated:now,deleted:false,images:[]});await store.save(state,next);await apply(store,vault,(await preview(store,vault)).token);const file=path.join(vault,'list.md'),text=await fs.readFile(file,'utf8');await fs.writeFile(file,text.replace('二项','修改 & 二项'));await apply(store,vault,(await preview(store,vault)).token);const result=(await store.readState()).memos[0];assert.equal(result.content,'标题\n- 一项\n- 修改 & 二项');assert.equal(result.html,'<p>标题</p><ul><li><p>一项</p></li><li><p>修改 &amp; 二项</p></li></ul>');await fs.writeFile(file,(await fs.readFile(file,'utf8')).replace('- 一项','不再是列表'));assert.equal((await preview(store,vault)).conflicts[0].reason,'rich_content_requires_review');assert.equal((await store.readState()).memos[0].html,result.html);
});
