 assets.set(second.path,image);p=await preview(store,vault,options);assert.equal(p.canApply,false);assert.ok(p.conflicts.some(c=>c.reason==='image_asset_invalid'));assets.delete(second.path);p=await preview(store,vault,options);assert.equal(p.canApply,false);assert.ok(p.conflicts.some(c=>c.reason==='image_asset_invalid'));await assert.rejects(apply(store,vault,p.token,options),/冲突/);assert.deepEqual((await store.readState()).memos[0].images,[image,other]);
