test('multiple edit conflicts are compared and resolved one at a time',async t=>{
 const root=await fs.mkdtemp(path.join(process.cwd(),'work','obsidian-test-'));t.after(()=>fs.rm(root,{recursive:true,force:true}));const vault=path.join(root,'vault');await fs.mkdir(vault);const store=new FileStore(path.join(root,'data'));let state=await store.init(),next=structuredClone(state),now=new Date().toISOString();for(const id of ['a','b'])next.memos.push({id,content:'原文 '+id,created:now,updated:now,deleted:false,images:[]});await store.save(state,next);await apply(store,vault,(await preview(store,vault)).token);for(const id of ['a','b']){const file=path.join(vault,id+'.md');await fs.writeFile(file,(await fs.readFile(file,'utf8')).replace('原文','Obsidian'));}state=await store.readState();next=structuredClone(state);for(const memo of next.memos)memo.content=memo.content.replace('原文','Fomo');await store.save(state,next);
 const resolve=require('../desktop/obsidian-sync.cjs').resolveConflict;let p=await preview(store,vault);assert.equal(p.conflicts.length,2);assert.equal(p.comparison.remaining,1);const first=p.comparison.id;await resolve(store,vault,p.token,first,'obsidian');p=await preview(store,vault);assert.equal(p.conflicts.length,1);assert.notEqual(p.comparison.id,first);await resolve(store,vault,p.token,p.comparison.id,'obsidian');p=await preview(store,vault);assert.deepEqual(p.conflicts,[]);assert.deepEqual(p.actions,[]);assert.ok((await store.readState()).memos.every(m=>m.content.startsWith('Obsidian')));
});
