test('preview follows files moved to a nested folder and ignores trash',async t=>{const root=await fs.mkdtemp(path.join(process.cwd(),'work','obsidian-test-'));t.after(()=>fs.rm(root,{recursive:true,force:true}));const vault=path.join(root,'vault');await fs.mkdir(path.join(vault,'nested'),{recursive:true});await fs.mkdir(path.join(vault,'.trash'));const store=new FileStore(path.join(root,'data'));await store.init();const text='---\nfomo_id: "n1"\nfomo_created: "2026-01-01T00:00:00.000Z"\n---\n正文';await fs.writeFile(path.join(vault,'nested','renamed.md'),text);await fs.writeFile(path.join(vault,'.trash','old.md'),'not a note');const value=await preview(store,vault);assert.equal(value.conflicts.length,0);assert.equal(value.actions[0].path,'nested/renamed.md');});

test('initial export records a baseline and detects a stale preview',async t=>{const root=await fs.mkdtemp(path.join(process.cwd(),'work','obsidian-test-'));t.after(()=>fs.rm(root,{recursive:true,force:true}));const vault=path.join(root,'vault');await fs.mkdir(vault);const store=new FileStore(path.join(root,'data'));let state=await store.init();const now=new Date().toISOString(),next=JSON.parse(JSON.stringify(state));next.memos.push({id:'new-1',content:'安全的纯文本',created:now,updated:now,deleted:false,images:[]});await store.save(state,next);let first=await preview(store,vault);await fs.writeFile(path.join(vault,'other.md'),'invalid');await assert.rejects(apply(store,vault,first.token),/过期/);await fs.unlink(path.join(vault,'other.md'));first=await preview(store,vault);const output=await apply(store,vault,first.token);assert.equal(output.exported,1);assert.match(await fs.readFile(path.join(vault,'new-1.md'),'utf8'),/安全的纯文本/);assert.deepEqual((await preview(store,vault)).actions,[]);});

test('first Obsidian import is backed up and creates a synchronized baseline',async t=>{const root=await fs.mkdtemp(path.join(process.cwd(),'work','obsidian-test-'));t.after(()=>fs.rm(root,{recursive:true,force:true}));const vault=path.join(root,'vault');await fs.mkdir(vault);const store=new FileStore(path.join(root,'data'));await store.init();const text='---\nfomo_id: "ob-1"\nfomo_created: "2026-01-01T00:00:00.000Z"\n---\n从 Obsidian 新建';await fs.writeFile(path.join(vault,'ob-1.md'),text);const p=await preview(store,vault),result=await apply(store,vault,p.token);assert.equal(result.imported,1);assert.equal((await store.readState()).memos[0].content,'从 Obsidian 新建');assert.equal((await preview(store,vault)).actions.length,0);assert.ok((await fs.readdir(path.join(store.directory,'backups'))).some(x=>x.startsWith('obsidian-import-')));assert.equal(await fs.readFile(path.join(vault,'ob-1.md'),'utf8'),text);});
