test('Obsidian text edit updates Fomo with a saved previous revision',async t=>{const root=await fs.mkdtemp(path.join(process.cwd(),'work','obsidian-test-'));t.after(()=>fs.rm(root,{recursive:true,force:true}));const vault=path.join(root,'vault');await fs.mkdir(vault);const store=new FileStore(path.join(root,'data'));let state=await store.init();const now=new Date().toISOString(),next=JSON.parse(JSON.stringify(state));next.memos.push({id:'n1',content:'旧正文',created:now,updated:now,deleted:false,images:[]});await store.save(state,next);await apply(store,vault,(await preview(store,vault)).token);const file=path.join(vault,'n1.md');await fs.writeFile(file,(await fs.readFile(file,'utf8')).replace('旧正文','新正文'));const p=await preview(store,vault);assert.equal(p.actions[0].type,'update_fomo');const result=await apply(store,vault,p.token);assert.equal(result.updated,1);const memo=(await store.readState()).memos[0];assert.equal(memo.content,'新正文');assert.ok(memo.history.some(h=>h.content==='旧正文'));assert.equal((await preview(store,vault)).actions.length,0);});
test('plain editor paragraphs roundtrip while preserving escaped HTML and history',async t=>{
 const root=await fs.mkdtemp(path.join(process.cwd(),'work','obsidian-test-'));t.after(()=>fs.rm(root,{recursive:true,force:true}));const vault=path.join(root,'vault');await fs.mkdir(vault);const store=new FileStore(path.join(root,'data'));let state=await store.init(),next=structuredClone(state),now=new Date().toISOString();
 next.memos.push({id:'n1',content:'旧 & 正文',html:'<p>旧 &amp; 正文</p>',created:now,updated:now,deleted:false,images:[]});await store.save(state,next);await apply(store,vault,(await preview(store,vault)).token);
 const file=path.join(vault,'n1.md'),previous=await fs.readFile(file,'utf8');await fs.writeFile(file,previous.replace('旧 & 正文','新 <正文> & 内容'));const p=await preview(store,vault);assert.equal(p.actions[0].type,'update_fomo');await apply(store,vault,p.token);
 const updated=(await store.readState()).memos[0];assert.equal(updated.content,'新 <正文> & 内容');assert.equal(updated.html,'<p>新 &lt;正文&gt; &amp; 内容</p>');assert.ok(updated.history.some(h=>h.content==='旧 & 正文'));assert.equal((await preview(store,vault)).actions.length,0);
});
test('multiline plain text roundtrips without changing the original line-break representation',async t=>{
 for(const [mode,html] of [['paragraphs','<p>第一行</p><p>第二行</p>'],['breaks','<p>第一行<br>第二行</p>']]){
  const root=await fs.mkdtemp(path.join(process.cwd(),'work','obsidian-test-'));t.after(()=>fs.rm(root,{recursive:true,force:true}));const vault=path.join(root,'vault');await fs.mkdir(vault);const store=new FileStore(path.join(root,'data'));let state=await store.init(),next=structuredClone(state),now=new Date().toISOString();
  next.memos.push({id:'n1',content:'第一行\n第二行',html,created:now,updated:now,deleted:false,images:[]});await store.save(state,next);await apply(store,vault,(await preview(store,vault)).token);
  const file=path.join(vault,'n1.md'),before=await fs.readFile(file,'utf8');await fs.writeFile(file,before.replace('第一行\n第二行','更新 & 一\n\n更新二'));await apply(store,vault,(await preview(store,vault)).token);
  const updated=(await store.readState()).memos[0];assert.equal(updated.content,'更新 & 一\n\n更新二');assert.equal(updated.html,mode==='paragraphs'?'<p>更新 &amp; 一</p><p></p><p>更新二</p>':'<p>更新 &amp; 一<br><br>更新二</p>');assert.ok(updated.history.some(h=>h.content==='第一行\n第二行'));assert.deepEqual((await preview(store,vault)).actions,[]);
 }
});
test('a simultaneous rich-text change blocks an external edit',async t=>{const root=await fs.mkdtemp(path.join(process.cwd(),'work','obsidian-test-'));t.after(()=>fs.rm(root,{recursive:true,force:true}));const vault=path.join(root,'vault');await fs.mkdir(vault);const store=new FileStore(path.join(root,'data'));let state=await store.init();const now=new Date().toISOString(),next=JSON.parse(JSON.stringify(state));next.memos.push({id:'n1',content:'正文',created:now,updated:now,deleted:false,images:[]});await store.save(state,next);await apply(store,vault,(await preview(store,vault)).token);const file=path.join(vault,'n1.md');await fs.writeFile(file,(await fs.readFile(file,'utf8')).replace('正文','外部'));state=await store.readState();const changed=JSON.parse(JSON.stringify(state));changed.memos[0].html='<p><strong>正文</strong></p>';await store.save(state,changed);const p=await preview(store,vault);assert.equal(p.conflicts[0].reason,'both_changed');await assert.rejects(apply(store,vault,p.token),/冲突/);assert.equal((await store.readState()).memos[0].html,'<p><strong>正文</strong></p>');});

test('matching copies can rebuild a lost baseline without changing either side',async t=>{const root=await fs.mkdtemp(path.join(process.cwd(),'work','obsidian-test-'));t.after(()=>fs.rm(root,{recursive:true,force:true}));const vault=path.join(root,'vault');await fs.mkdir(vault);const store=new FileStore(path.join(root,'data'));let state=await store.init();const now=new Date().toISOString(),desired=JSON.parse(JSON.stringify(state));desired.memos.push({id:'n1',content:'同样内容',created:now,updated:now,deleted:false,images:[]});await store.save(state,desired);const file=path.join(vault,'renamed.md'),text=require('../desktop/obsidian-sync-plan.cjs').encode((await store.readState()).memos[0]);await fs.writeFile(file,text);const p=await preview(store,vault);assert.equal(p.actions[0].type,'adopt');assert.equal((await apply(store,vault,p.token)).adopted,1);assert.equal(await fs.readFile(file,'utf8'),text);assert.equal((await preview(store,vault)).actions.length,0);});

test('Fomo edit uses compare-and-swap and saves the previous Obsidian text',async t=>{const root=await fs.mkdtemp(path.join(process.cwd(),'work','obsidian-test-'));t.after(()=>fs.rm(root,{recursive:true,force:true}));const vault=path.join(root,'vault');await fs.mkdir(vault);const store=new FileStore(path.join(root,'data'));let state=await store.init();const now=new Date().toISOString(),next=JSON.parse(JSON.stringify(state));next.memos.push({id:'n1',content:'旧',created:now,updated:now,deleted:false,images:[]});await store.save(state,next);await apply(store,vault,(await preview(store,vault)).token);state=await store.readState();const edited=JSON.parse(JSON.stringify(state));edited.memos[0].content='Fomo 新';await store.save(state,edited);const p=await preview(store,vault);assert.equal(p.actions[0].type,'export');await assert.rejects(apply(store,vault,p.token),/原子文件操作不可用/);const result=await apply(store,vault,p.token,{replaceFile:async({root,path:rel,expected,replacement})=>{const file=path.join(root,rel),current=await fs.readFile(file,'utf8');assert.equal(current,expected);await fs.writeFile(file,replacement);}});assert.equal(result.exported,1);assert.match(await fs.readFile(path.join(vault,'n1.md'),'utf8'),/Fomo 新/);assert.equal((await preview(store,vault)).actions.length,0);assert.ok((await fs.readdir(path.join(store.directory,'backups'))).some(x=>x.startsWith('obsidian-before-write-')));});
test('failed compare-and-swap preserves the competing Obsidian edit and creates no baseline advance',async t=>{const root=await fs.mkdtemp(path.join(process.cwd(),'work','obsidian-test-'));t.after(()=>fs.rm(root,{recursive:true,force:true}));const vault=path.join(root,'vault');await fs.mkdir(vault);const store=new FileStore(path.join(root,'data'));let state=await store.init(),now=new Date().toISOString(),next=JSON.parse(JSON.stringify(state));next.memos.push({id:'n1',content:'旧',created:now,updated:now,deleted:false,images:[]});await store.save(state,next);await apply(store,vault,(await preview(store,vault)).token);state=await store.readState();next=JSON.parse(JSON.stringify(state));next.memos[0].content='Fomo';await store.save(state,next);const p=await preview(store,vault);await assert.rejects(apply(store,vault,p.token,{replaceFile:async({root,path:rel,expected})=>{const file=path.join(root,rel);await fs.writeFile(file,expected.replace('旧','Obsidian'));throw Error('并发变化');}}),/并发变化/);assert.equal((await preview(store,vault)).conflicts[0].reason,'both_changed');assert.match(await fs.readFile(path.join(vault,'n1.md'),'utf8'),/Obsidian/);});

test('a manifest write failure after Obsidian update can recover the shared baseline',async t=>{const root=await fs.mkdtemp(path.join(process.cwd(),'work','obsidian-test-'));t.after(()=>fs.rm(root,{recursive:true,force:true}));const vault=path.join(root,'vault');await fs.mkdir(vault);const store=new FileStore(path.join(root,'data'));let state=await store.init(),now=new Date().toISOString(),next=JSON.parse(JSON.stringify(state));next.memos.push({id:'n1',content:'旧',created:now,updated:now,deleted:false,images:[]});await store.save(state,next);await apply(store,vault,(await preview(store,vault)).token);state=await store.readState();next=JSON.parse(JSON.stringify(state));next.memos[0].content='新';await store.save(state,next);const p=await preview(store,vault),io=store.io;store.io={...io,rename:async(from,to)=>{if(path.basename(to).startsWith('obsidian-sync-'))throw Error('模拟清单写入失败');return io.rename(from,to);}};try{await assert.rejects(apply(store,vault,p.token,{replaceFile:async({root,path:rel,expected,replacement})=>{const file=path.join(root,rel);assert.equal(await fs.readFile(file,'utf8'),expected);await fs.writeFile(file,replacement);}}),/同步清单未更新/);}finally{store.io=io;}const recovery=await preview(store,vault);assert.equal(recovery.actions[0].type,'adopt');await apply(store,vault,recovery.token);assert.deepEqual((await preview(store,vault)).actions,[]);});
test('lost acknowledgement after a successful vault write recovers without repeating the write',async t=>{
 const root=await fs.mkdtemp(path.join(process.cwd(),'work','obsidian-test-'));t.after(()=>fs.rm(root,{recursive:true,force:true}));const vault=path.join(root,'vault');await fs.mkdir(vault);
 const store=new FileStore(path.join(root,'data'));let state=await store.init(),now=new Date().toISOString(),next=structuredClone(state);next.memos.push({id:'n1',content:'旧',created:now,updated:now,deleted:false,images:[]});await store.save(state,next);await apply(store,vault,(await preview(store,vault)).token);
 state=await store.readState();next=structuredClone(state);next.memos[0].content='新';await store.save(state,next);
 const plan=await preview(store,vault,{replaceFile:()=>{}});let writes=0;
 await assert.rejects(apply(store,vault,plan.token,{replaceFile:async({root,path:rel,expected,replacement})=>{const file=path.join(root,rel);assert.equal(await fs.readFile(file,'utf8'),expected);await fs.writeFile(file,replacement);writes++;throw Error('连接断开');}}),/连接断开/);
 const recovery=await preview(store,vault);assert.deepEqual(recovery.actions.map(a=>a.type),['adopt']);assert.equal(recovery.canApply,true);await apply(store,vault,recovery.token);
 assert.equal(writes,1);assert.match(await fs.readFile(path.join(vault,'n1.md'),'utf8'),/新/);assert.deepEqual((await preview(store,vault)).actions,[]);
});
